// Six small (64x64) but genuinely valid, independently-decodable JPEGs with added Gaussian
// noise texture, generated and round-trip-verified via Pillow/NumPy. Solid-color swatches
// (the first version of this fixture) turned out to be a bad test double: the heuristic
// classifier's texture feature is a real discriminating signal, so a flat color sits right at
// the chaincode's confidence threshold and produces flaky pass/fail depending on which color
// happened to be picked. These are textured enough to classify with comfortable confidence
// margin (verified >=0.35, threshold is 0.3) while still being tiny, deterministic fixtures -
// each a distinct color/hash so tests creating multiple non-duplicate observations don't
// accidentally trip exact-hash duplicate detection against each other.
const BASE64_IMAGES: Record<string, string> = {
  A:
    '',
  B:
    '',
  C:
    '',
  D:
    '',
  E:
    '',
  F:
    '',
};

export type TestImageKey = keyof typeof BASE64_IMAGES;

/**
 * Returns the fixture with a random trailer appended after the JPEG's EOI marker - decoders
 * (verified against Pillow) ignore trailing bytes and decode identical pixels, but the file's
 * sha256 changes every call. This matters because the Fabric ledger, unlike Postgres, is never
 * reset between test runs (see docs/BLOCKCHAIN.md - that's the whole point of a ledger), so a
 * static fixture's evidence hash from a previous successful run would permanently collide with
 * the chaincode's on-chain duplicate-hash guard on every future run.
 */
export function getTestImage(key: TestImageKey): Buffer {
  const base = Buffer.from(BASE64_IMAGES[key], 'base64');
  const trailer = Buffer.from(`run-${Date.now()}-${Math.random().toString(36).slice(2)}`, 'utf8');
  return Buffer.concat([base, trailer]);
}
